import { useState, useEffect, useRef } from "react";
import { motion, useScroll, useTransform, AnimatePresence } from "framer-motion";

const user = { firstName: "Alexandre", lastName: "Moreau", email: "a.moreau@luxury.com" };

const NAV_ITEMS = ["Collection", "Configurateur", "Conciergerie", "Expériences"];

const STATS = [
  { value: "12", label: "Véhicules Disponibles", suffix: "" },
  { value: "4.9", label: "Note Conciergerie", suffix: "★" },
  { value: "24", label: "Service Client", suffix: "/7" },
  { value: "100", label: "Satisfaction Client", suffix: "%" },
];

const SERVICES = [
  {
    num: "01",
    title: "Collection Exclusive",
    desc: "Accédez à notre sélection privée de Porsche et Mercedes d'exception, chaque modèle soigneusement sélectionné pour son raffinement.",
    cta: "Explorer",
    accent: "#C9A84C",
  },
  {
    num: "02",
    title: "Essai Privé",
    desc: "Vivez une expérience de conduite intime et personnalisée sur des circuits privés ou en ville, accompagné de votre conseiller dédié.",
    cta: "Réserver",
    accent: "#E8D5A3",
  },
  {
    num: "03",
    title: "Configuration Sur Mesure",
    desc: "Personnalisez chaque détail de votre véhicule — finitions, sellerie, options techniques — selon vos désirs les plus exigeants.",
    cta: "Configurer",
    accent: "#C9A84C",
  },
  {
    num: "04",
    title: "Conciergerie Premium",
    desc: "Votre conseiller personnel reste disponible à toute heure pour répondre à chaque demande avec discrétion et excellence.",
    cta: "Contacter",
    accent: "#E8D5A3",
  },
];

const FLEET = [
  { brand: "PORSCHE", model: "911 GT3 RS", year: "2025", tag: "DISPONIBLE", color: "#C9A84C" },
  { brand: "MERCEDES", model: "AMG GT Black", year: "2025", tag: "SUR COMMANDE", color: "#8A8A8A" },
  { brand: "PORSCHE", model: "Taycan Turbo S", year: "2024", tag: "DISPONIBLE", color: "#C9A84C" },
];

function useCountUp(end, duration = 2000, start = false) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!start) return;
    const numEnd = parseFloat(end);
    const step = numEnd / (duration / 16);
    let current = 0;
    const timer = setInterval(() => {
      current = Math.min(current + step, numEnd);
      setCount(current);
      if (current >= numEnd) clearInterval(timer);
    }, 16);
    return () => clearInterval(timer);
  }, [end, duration, start]);
  return count;
}

function StatCard({ value, label, suffix, index, visible }) {
  const num = useCountUp(value, 1800 + index * 200, visible);
  const display = value.includes(".") ? num.toFixed(1) : Math.round(num);
  return (
    <motion.div
      initial={{ opacity: 0, y: 30 }}
      animate={visible ? { opacity: 1, y: 0 } : {}}
      transition={{ duration: 0.8, delay: index * 0.12, ease: [0.22, 1, 0.36, 1] }}
      style={{
        padding: "36px 28px",
        borderTop: "1px solid rgba(201,168,76,0.2)",
        position: "relative",
        overflow: "hidden",
      }}
    >
      <div style={{
        position: "absolute", top: 0, left: 0, width: "2px", height: "0%",
        background: "linear-gradient(to bottom, #C9A84C, transparent)",
        animation: visible ? "lineGrow 1.2s forwards" : "none",
        animationDelay: `${index * 0.12 + 0.3}s`,
      }} />
      <div style={{
        fontSize: "clamp(40px, 5vw, 64px)", fontFamily: "'Playfair Display', serif",
        fontWeight: 300, color: "#C9A84C", lineHeight: 1, marginBottom: 10,
        letterSpacing: "-1px",
      }}>
        {display}{suffix}
      </div>
      <div style={{ fontSize: 11, letterSpacing: "3px", color: "rgba(255,255,255,0.45)", textTransform: "uppercase" }}>
        {label}
      </div>
    </motion.div>
  );
}

function ServiceCard({ service, index }) {
  const [hovered, setHovered] = useState(false);
  return (
    <motion.div
      initial={{ opacity: 0, y: 50 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.9, delay: index * 0.1, ease: [0.22, 1, 0.36, 1] }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        position: "relative", padding: "48px 40px", cursor: "pointer",
        borderBottom: "1px solid rgba(255,255,255,0.06)",
        borderRight: index % 2 === 0 ? "1px solid rgba(255,255,255,0.06)" : "none",
        overflow: "hidden",
        transition: "background 0.5s ease",
        background: hovered ? "rgba(201,168,76,0.03)" : "transparent",
      }}
    >
      <motion.div
        animate={{ scaleX: hovered ? 1 : 0 }}
        initial={{ scaleX: 0 }}
        transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
        style={{
          position: "absolute", left: 0, top: 0, bottom: 0, width: "2px",
          background: "linear-gradient(to bottom, #C9A84C, rgba(201,168,76,0.1))",
          transformOrigin: "top",
        }}
      />
      <div style={{
        fontSize: 11, letterSpacing: "6px", color: "rgba(201,168,76,0.4)",
        marginBottom: 28, fontWeight: 300,
      }}>
        {service.num}
      </div>
      <h3 style={{
        fontFamily: "'Playfair Display', serif", fontSize: "clamp(22px, 2.5vw, 30px)",
        fontWeight: 300, color: "#fff", marginBottom: 18, lineHeight: 1.2,
        letterSpacing: "-0.5px",
      }}>
        {service.title}
      </h3>
      <p style={{
        fontSize: 14, color: "rgba(255,255,255,0.5)", lineHeight: 2,
        marginBottom: 36, maxWidth: 380,
      }}>
        {service.desc}
      </p>
      <motion.div
        animate={{ gap: hovered ? "20px" : "10px" }}
        style={{
          display: "flex", alignItems: "center", gap: "10px",
          color: "#C9A84C", fontSize: 10, letterSpacing: "5px",
          textTransform: "uppercase", fontWeight: 600,
        }}
      >
        <span>{service.cta}</span>
        <motion.div
          animate={{ x: hovered ? 4 : 0, opacity: hovered ? 1 : 0.6 }}
          transition={{ duration: 0.3 }}
          style={{ fontSize: 18 }}
        >
          →
        </motion.div>
      </motion.div>
    </motion.div>
  );
}

export default function Dashboard() {
  const [scrollY, setScrollY] = useState(0);
  const [statsVisible, setStatsVisible] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [menuOpen, setMenuOpen] = useState(false);
  const statsRef = useRef(null);

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener("scroll", handleScroll);
    const clock = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => { window.removeEventListener("scroll", handleScroll); clearInterval(clock); };
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setStatsVisible(true); },
      { threshold: 0.3 }
    );
    if (statsRef.current) observer.observe(statsRef.current);
    return () => observer.disconnect();
  }, []);

  const timeStr = currentTime.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" });
  const dateStr = currentTime.toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" });

  const navBg = scrollY > 60
    ? "rgba(2,2,2,0.95)"
    : "transparent";
  const navBorder = scrollY > 60
    ? "rgba(201,168,76,0.1)"
    : "transparent";

  return (
    <div style={{
      minHeight: "100vh",
      background: "#020202",
      fontFamily: "'Cormorant Garamond', 'Georgia', serif",
      color: "#fff",
      overflowX: "hidden",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,300;0,400;1,300;1,400&family=Cormorant+Garamond:wght@300;400;500&family=Jost:wght@200;300;400;500&display=swap');
        * { margin: 0; padding: 0; box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        body { background: #020202; }
        ::-webkit-scrollbar { width: 2px; }
        ::-webkit-scrollbar-track { background: #020202; }
        ::-webkit-scrollbar-thumb { background: #C9A84C; border-radius: 1px; }
        @keyframes lineGrow { from { height: 0% } to { height: 100% } }
        @keyframes pulse { 0%,100% { opacity: 1 } 50% { opacity: 0.4 } }
        @keyframes rotateSlow { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }
        @keyframes float { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-20px) } }
        @keyframes shimmer { 0% { transform: translateX(-100%) skewX(-15deg) } 100% { transform: translateX(200%) skewX(-15deg) } }
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(40px) } to { opacity: 1; transform: translateY(0) } }
        @keyframes scanLine { 0% { top: -2px } 100% { top: 100% } }
      `}</style>

      {/* NAV */}
      <nav style={{
        position: "fixed", top: 0, left: 0, right: 0, zIndex: 100,
        padding: "0 60px", height: 80,
        display: "flex", alignItems: "center", justifyContent: "space-between",
        background: navBg, borderBottom: `1px solid ${navBorder}`,
        transition: "all 0.6s cubic-bezier(0.22, 1, 0.36, 1)",
        backdropFilter: scrollY > 60 ? "blur(20px)" : "none",
        fontFamily: "'Jost', sans-serif",
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{
            width: 36, height: 36, border: "1px solid rgba(201,168,76,0.5)",
            display: "flex", alignItems: "center", justifyContent: "center",
            position: "relative",
          }}>
            <div style={{ width: 14, height: 14, border: "1px solid #C9A84C", transform: "rotate(45deg)" }} />
          </div>
          <div>
            <div style={{ fontSize: 13, letterSpacing: "6px", color: "#C9A84C", fontWeight: 300 }}>LUXURY</div>
            <div style={{ fontSize: 9, letterSpacing: "4px", color: "rgba(255,255,255,0.3)", marginTop: -2 }}>AUTO PRESTIGE</div>
          </div>
        </div>

        <div style={{ display: "flex", gap: 44 }}>
          {NAV_ITEMS.map(item => (
            <a key={item} href="#" style={{
              fontSize: 10, letterSpacing: "4px", color: "rgba(255,255,255,0.45)",
              textTransform: "uppercase", textDecoration: "none",
              transition: "color 0.3s", fontFamily: "'Jost', sans-serif",
              fontWeight: 300,
            }}
              onMouseEnter={e => e.target.style.color = "#C9A84C"}
              onMouseLeave={e => e.target.style.color = "rgba(255,255,255,0.45)"}
            >
              {item}
            </a>
          ))}
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontSize: 11, color: "#C9A84C", letterSpacing: "2px", fontFamily: "'Jost', sans-serif" }}>{timeStr}</div>
            <div style={{ fontSize: 9, color: "rgba(255,255,255,0.3)", letterSpacing: "2px", textTransform: "capitalize", fontFamily: "'Jost', sans-serif" }}>
              {dateStr}
            </div>
          </div>
          <div style={{
            width: 42, height: 42, borderRadius: "50%",
            background: "linear-gradient(135deg, rgba(201,168,76,0.2), rgba(201,168,76,0.05))",
            border: "1px solid rgba(201,168,76,0.3)",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 12, color: "#C9A84C", letterSpacing: "1px", cursor: "pointer",
            fontFamily: "'Playfair Display', serif",
          }}>
            {user.firstName[0]}{user.lastName[0]}
          </div>
        </div>
      </nav>

      {/* HERO */}
      <section style={{ position: "relative", minHeight: "100vh", display: "flex", alignItems: "center", overflow: "hidden" }}>

        {/* BG layers */}
        <div style={{
          position: "absolute", inset: 0,
          background: "radial-gradient(ellipse at 20% 50%, rgba(201,168,76,0.06) 0%, transparent 60%)",
        }} />
        <div style={{
          position: "absolute", inset: 0,
          backgroundImage: `
            linear-gradient(rgba(201,168,76,0.04) 1px, transparent 1px),
            linear-gradient(90deg, rgba(201,168,76,0.04) 1px, transparent 1px)
          `,
          backgroundSize: "80px 80px",
          maskImage: "radial-gradient(ellipse at 30% 50%, black 20%, transparent 70%)",
        }} />

        {/* Vertical decorative lines */}
        {[...Array(3)].map((_, i) => (
          <div key={i} style={{
            position: "absolute", top: 0, bottom: 0,
            left: `${25 + i * 25}%`,
            width: "1px",
            background: "linear-gradient(to bottom, transparent, rgba(201,168,76,0.08), transparent)",
            opacity: 0.5,
          }} />
        ))}

        {/* Animated circle */}
        <div style={{
          position: "absolute", right: "-100px", top: "50%", transform: "translateY(-50%)",
          width: 700, height: 700,
          border: "1px solid rgba(201,168,76,0.06)",
          borderRadius: "50%", animation: "rotateSlow 60s linear infinite",
        }}>
          <div style={{
            position: "absolute", inset: "15%",
            border: "1px solid rgba(201,168,76,0.1)",
            borderRadius: "50%",
          }} />
          <div style={{
            position: "absolute", inset: "30%",
